/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This module demonstrates Scala's type system with:
 * - Sealed traits and case classes for ADTs
 * - Variance annotations (covariant/contravariant)
 * - Option/Either for error handling
 * - Pattern matching and functional programming
 * - Immutability by default
 */

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.util.{Try, Success, Failure}
import scala.collection.immutable.Seq

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object String extends TokenType { val value = "string" }
  case object Numeric extends TokenType { val value = "numeric" }
  case object Temporal extends TokenType { val value = "temporal" }
  case object Structured extends TokenType { val value = "structured" }
  case object Binary extends TokenType { val value = "binary" }
  case object Null extends TokenType { val value = "null" }
}

// ============================================================================
// Core Token Classes
// ============================================================================

/**
 * Immutable token representation.
 */
case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  /**
   * Return new token with additional metadata.
   */
  def withMetadata(additionalMetadata: (String, Any)*): Token = {
    copy(metadata = metadata ++ additionalMetadata.toMap)
  }
}

/**
 * Mutable batch of tokens - contrast with immutable Token.
 */
class MutableTokenBatch {
  private var tokens: List[Token] = List.empty
  private var _processed: Boolean = false

  def add(token: Token): Unit = {
    if (_processed) {
      throw new RuntimeException("Batch already processed")
    }
    tokens = tokens :+ token
  }

  def markProcessed(): Unit = {
    _processed = true
  }

  def getTokens: List[Token] = tokens
  def isProcessed: Boolean = _processed
}

// ============================================================================
// Protocol-like traits (structural typing alternatives)
// ============================================================================

trait Tokenizable {
  def toToken: String
}

trait HasLength {
  def length: Int
}

trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/**
 * Covariant container - can return subtypes.
 */
class TokenContainer[+T](private val items: Seq[T]) {
  def getAll: Seq[T] = items

  def mapTokens[R](func: T => R): Seq[R] = items.map(func)
}

/**
 * Contravariant sink - can accept supertypes.
 */
class TokenSink[-T] {
  private var _received: List[Any] = List.empty

  def receive(item: T): Unit = {
    _received = _received :+ item
  }

  def drain(): List[Any] = {
    val result = _received
    _received = List.empty
    result
  }
}

/**
 * Invariant handler - exact type matching required.
 */
class BivariantHandler[T](private var _value: T) {
  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

/**
 * Abstract base tokenizer with generic input type.
 */
trait BaseTokenizer[T] {
  /**
   * Convert value to token.
   */
  def tokenize(value: T): Token

  /**
   * Convert multiple values to tokens.
   */
  def tokenizeBatch(values: Iterable[T]): Seq[Token] = {
    values.map(tokenize).toSeq
  }
}

/**
 * String tokenizer with various normalization options.
 */
class StringTokenizer(
  lowercase: Boolean = false,
  uppercase: Boolean = false,
  stripWhitespace: Boolean = true,
  maxLength: Option[Int] = None,
  prefix: String = "",
  suffix: String = ""
) extends BaseTokenizer[String] {

  def tokenize(value: String): Token = {
    var processed = value

    if (stripWhitespace) {
      processed = processed.trim
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (uppercase) {
      processed = processed.toUpperCase
    }

    maxLength.foreach { max =>
      if (processed.length > max) {
        processed = processed.take(max)
      }
    }

    processed = prefix + processed + suffix

    val metadata = Map(
      "original_length" -> value.length,
      "processed_length" -> processed.length
    )

    Token(processed, TokenType.String, metadata)
  }
}

/**
 * Numeric tokenizer for int, long, float, double, and BigDecimal.
 */
class NumericTokenizer(
  precision: Option[Int] = None,
  useScientific: Boolean = false,
  prefix: String = "",
  suffix: String = ""
) extends BaseTokenizer[Any] {

  def tokenize(value: Any): Token = {
    val numValue: BigDecimal = value match {
      case i: Int => BigDecimal(i)
      case l: Long => BigDecimal(l)
      case f: Float => BigDecimal(f.toDouble)
      case d: Double => BigDecimal(d)
      case bd: BigDecimal => bd
      case _ => throw new IllegalArgumentException(s"Unsupported numeric type: ${value.getClass}")
    }

    val formatted = precision match {
      case Some(p) => numValue.setScale(p, BigDecimal.RoundingMode.HALF_UP).toString
      case None => numValue.toString
    }

    val processed = prefix + formatted + suffix

    val metadata = Map(
      "original_value" -> value,
      "numeric_type" -> value.getClass.getSimpleName
    )

    Token(processed, TokenType.Numeric, metadata)
  }
}

/**
 * Temporal tokenizer for dates and datetimes.
 */
class TemporalTokenizer(
  dateFormat: String = "yyyy-MM-dd",
  datetimeFormat: String = "yyyy-MM-dd'T'HH:mm:ss"
) extends BaseTokenizer[Any] {

  private val dateFormatter = DateTimeFormatter.ofPattern(dateFormat)
  private val datetimeFormatter = DateTimeFormatter.ofPattern(datetimeFormat)

  def tokenize(value: Any): Token = {
    val (formatted, temporalType) = value match {
      case d: LocalDate =>
        (d.format(dateFormatter), "date")
      case dt: LocalDateTime =>
        (dt.format(datetimeFormatter), "datetime")
      case _ =>
        throw new IllegalArgumentException(s"Unsupported temporal type: ${value.getClass}")
    }

    val metadata = Map(
      "temporal_type" -> temporalType,
      "format" -> (if (temporalType == "date") dateFormat else datetimeFormat)
    )

    Token(formatted, TokenType.Temporal, metadata)
  }
}

/**
 * Universal tokenizer that handles multiple types.
 */
class UniversalTokenizer(
  stringTokenizer: Option[StringTokenizer] = None,
  numericTokenizer: Option[NumericTokenizer] = None,
  temporalTokenizer: Option[TemporalTokenizer] = None,
  handleNull: Boolean = true,
  nullToken: String = "<NULL>"
) extends BaseTokenizer[Any] {

  private val defaultStringTokenizer = stringTokenizer.getOrElse(new StringTokenizer())
  private val defaultNumericTokenizer = numericTokenizer.getOrElse(new NumericTokenizer())
  private val defaultTemporalTokenizer = temporalTokenizer.getOrElse(new TemporalTokenizer())

  def tokenize(value: Any): Token = {
    value match {
      case null if handleNull =>
        Token(nullToken, TokenType.Null, Map("is_null" -> true))

      case null =>
        throw new IllegalArgumentException("Null values not supported")

      case None if handleNull =>
        Token(nullToken, TokenType.Null, Map("is_null" -> true))

      case Some(v) =>
        tokenize(v)

      case s: String =>
        defaultStringTokenizer.tokenize(s)

      case _: Int | _: Long | _: Float | _: Double | _: BigDecimal =>
        defaultNumericTokenizer.tokenize(value)

      case _: LocalDate | _: LocalDateTime =>
        defaultTemporalTokenizer.tokenize(value)

      case seq: Seq[_] =>
        val tokens = seq.map(tokenize)
        val concatenated = tokens.map(_.value).mkString(",")
        Token(s"[$concatenated]", TokenType.Structured, Map("element_count" -> seq.length))

      case map: Map[_, _] =>
        val pairs = map.map { case (k, v) =>
          s"${tokenize(k).value}:${tokenize(v).value}"
        }.mkString(",")
        Token(s"{$pairs}", TokenType.Structured, Map("key_count" -> map.size))

      case t: Tokenizable =>
        Token(t.toToken, TokenType.String, Map("custom_tokenizable" -> true))

      case _ =>
        Token(value.toString, TokenType.String, Map("fallback" -> true))
    }
  }
}

/**
 * Simple whitespace-based tokenizer for text processing.
 */
class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {

  private val punctuation = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) {
      return None
    }

    maxLength.foreach { max =>
      if (processed.length > max) {
        processed = processed.take(max)
      }
    }

    if (processed.isEmpty) None else Some(processed)
  }

  /**
   * Split text by whitespace and return list of tokens.
   */
  def tokenize(text: String): Seq[Token] = {
    val words = text.split("\\s+")
    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.String,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toSeq
  }

  /**
   * Split text by whitespace and return list of token strings.
   */
  def tokenizeToStrings(text: String): Seq[String] = {
    tokenize(text).map(_.value)
  }

  /**
   * Tokenize text and return tokens with character positions.
   */
  def tokenizeWithPositions(text: String): Seq[(String, Int, Int)] = {
    val result = scala.collection.mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    text.split("\\s+").foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toSeq
  }

  /**
   * Return the number of tokens in the text.
   */
  def countTokens(text: String): Int = {
    tokenize(text).length
  }
}

